import re


def level(line):
    found = re.search(r"ERR|WARN|INFO", line)
    if found is None:
        return "UNKNOWN"
    return found.group()


def stamp(line):
    found = re.search(r"\d{4}-\d{2}-\d{2}", line)
    if found is None:
        return None
    return found.group()


print(level("2041-03-02 ERR north sensor cold"))
